# Better approach: flood fill from edges, unvisited bg cells are enclosed

def find_enclosed_regions(grid):
    rows = len(grid)
    cols = len(grid[0])

    border_color = 2
    bg_color = 8
    fill_color = 4

    # Flood fill from edges to mark all "open" regions
    visited = [[False]*cols for _ in range(rows)]

    # Start from all edge cells that are background color
    start_positions = []
    for c in range(cols):
        if grid[0][c] == bg_color:
            start_positions.append((0, c))
        if grid[rows-1][c] == bg_color:
            start_positions.append((rows-1, c))
    for r in range(rows):
        if grid[r][0] == bg_color:
            start_positions.append((r, 0))
        if grid[r][cols-1] == bg_color:
            start_positions.append((r, cols-1))

    # Also add interior bg cells adjacent to edges
    for r in range(1, rows-1):
        for c in range(1, cols-1):
            if grid[r][c] == bg_color:
                start_positions.append((r, c))

    # Run BFS/DFS from all start positions
    queue = [pos for pos in start_positions]
    head = 0
    while head < len(queue):
        r, c = queue[head]
        head += 1
        visited[r][c] = True

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited[nr][nc] and grid[nr][nc] == bg_color:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Unvisited background cells are enclosed regions
    enclosed_regions = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg_color and not visited[r][c]:
                enclosed_regions.append((r, c))

    return enclosed_regions

