# The key insight: we need to flood-fill through the background to find ALL connected regions
# An "enclosed" region is one that is surrounded by borders (border_color)

# Let's first identify connected components of background color
def find_enclosed_regions(grid, border_color=2, bg_color=8):
    rows = len(grid)
    cols = len(grid[0])

    if border_color != 5:
        bg_color = 9  # Demo had bg=9, border=5

    visited = [[False]*cols for _ in range(rows)]
    components = []  # List of lists of (r,c)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg_color and not visited[r][c]:
                # Start BFS/DFS
                component = [(r, c)]
                qr, qc = r, c
                visited[r][c] = True

                q = [(qr, qc)]
                head = 0
                while head < len(q):
                    cr, cc = q[head]
                    head += 1

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == bg_color:
                                visited[nr][nc] = True
                                component.append((nr, nc))
                                q.append((nr, nc))

                components.append(component)

    # Now check which components are enclosed (surrounded by border_color)
    # A component is enclosed if none of its neighbors are non-bg-color that are not border
    # Actually, let's check: for each cell in component, check if any neighbor is border_color
    # If ALL neighbors of ALL cells are border_color or other component cells, it's enclosed

    enclosed = []
    for comp in components:
        # Get all perimeter cells (cells with a non-bg neighbor)
        perimeter = set()
        has_border = False

        for (r, c) in comp:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == border_color:
                        has_border = True
                    elif grid[nr][nc] != bg_color:
                        # Not border color and not bg color - that's a non-border obstacle
                        pass  # Actually this can't happen if grid only has bg and border

        # If all boundary neighbors are border_color, it's enclosed
        all_border_or_in_comp = False
        for (r, c) in comp:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] != border_color and grid[nr][nc] != bg_color:
                        # This shouldn't happen
                        pass
                if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
                    # Grid boundary counts as enclosing?
                    all_border_or_in_comp = False  # Touches edge - not enclosed

        # Actually: if component touches grid boundary, it can't be enclosed
        touches_edge = False
        for (r, c) in comp:
            if r == 0 or r == rows-1 or c == 0 or c == cols-1:
                touches_edge = True
                break

        if not touches_edge and all_border_or_in_comp:
            enclosed.append(comp)

    return enclosed

# Test on demo
