def find_enclosed_v2(grid, border_color=5, bg_color=9):
    rows = len(grid)
    cols = len(grid[0])
    components = []

    visited = [[False]*cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg_color and not visited[r][c]:
                component = [(r, c)]
                visited[r][c] = True
                q = [(r, c)]
                head = 0
                while head < len(q):
                    cr, cc = q[head]
                    head += 1
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == bg_color:
                                visited[nr][nc] = True
                                component.append((nr, nc))
                                q.append((nr, nc))
                components.append(component)

    enclosed = []
    for comp in components:
        touches_edge = any(r == 0 or r == rows-1 or c == 0 or c == cols-1 for (r, c) in comp)
        if not touches_edge:
            enclosed.append(comp)
    return enclosed

